function guessSub(asset) {
  const a = (asset || "").toUpperCase();
  if (/XAU|XAG|GOLD|SILVER/.test(a)) return "Oro/Metales";
  if (/NAS|US100|US30|US500|SPX|DJI|DAX|GER|UK100|JP225|NDX|USTEC/.test(a)) return "Índices";
  return "Forex";
}

// Tamaño de 1 pip (o punto) expresado en precio
function guessPip(asset, category, sub) {
  if (category === "SINTETICO") return 1;
  const a = (asset || "").toUpperCase();
  if (/XAU|GOLD/.test(a)) return 0.1;
  if (/XAG|SILVER/.test(a)) return 0.01;
  if (/JPY/.test(a)) return 0.01;
  if (sub === "Índices" || guessSub(a) === "Índices") return 1;
  return 0.0001;
}

