function parseTpsText(text) {
  return String(text || "")
    .split(/[,;\s]+/)
    .map((tok) => {
      if (/^open$/i.test(tok)) return "OPEN";
      const n = num(tok);
      return n;
    })
    .filter((x) => x !== null && x !== "");
}

