/* ----------------------------- Formulario de señal ----------------------------- */
function emptyForm(category, sub, broker) {
  const cat = category || "CFD";
  return {
    id: null,
    date: localDate(),
    category: cat,
    sub: cat === "CFD" ? sub || "Forex" : "",
    broker: cat === "SINTETICO" ? broker || "WELTRADE" : "",
    asset: "",
    direction: "BUY",
    entry1: "",
    entry2: "",
    activation: "E1",
    sl: "",
    tpsText: "",
    pipSize: cat === "CFD" ? "0.0001" : "1",
    discarded: false,
    chart: "",
    img: "",
    raw: "",
    notes: "",
    tagsText: "VIP Signal",
    legs: {},
  };
}

const toForm = (t) => ({
  ...t,
  tpsText: (t.tps || []).join(", "),
  tagsText: (t.tags || []).join(", "),
  pipSize: String(t.pipSize ?? ""),
  entry2: t.entry2 ?? "",
});

function TradeForm({ initial, onCancel, onSave }) {
  const [f, setF] = useState(initial);
  const [err, setErr] = useState("");
  const [pipTouched, setPipTouched] = useState(!!initial.id);
  const set = (k, v) => setF((p) => ({ ...p, [k]: v }));

  // Clasificación automática: Sintético (DERIV / WELTRADE) o CFD según el activo
  useEffect(() => {
    const c = classifyAsset(f.asset);
    if (!c) return;
    setF((p) => ({ ...p, category: c.category, sub: c.category === "CFD" ? c.sub || p.sub || "Forex" : "", broker: c.category === "SINTETICO" ? c.broker : "" }));
  }, [f.asset]);

  // El tamaño del pip/punto se sugiere según el activo (editable)
  useEffect(() => {
    if (pipTouched) return;
    setF((p) => ({ ...p, pipSize: String(guessPip(p.asset, p.category, p.sub)) }));
  }, [f.asset, f.category, f.sub, pipTouched]);

  const addImage = async (file) => {
    if (!file || !file.type.startsWith("image/")) return;
    try { set("img", await compressImage(file)); } catch (e) { setErr("No se pudo leer la imagen."); }
  };
  const onPasteImg = (e) => {
    const it = Array.from(e.clipboardData?.items || []).find((i) => i.type.startsWith("image/"));
    if (it) { e.preventDefault(); addImage(it.getAsFile()); }
  };

  const submit = (e) => {
    e.preventDefault();
    if (!f.asset.trim()) return setErr("El activo es obligatorio.");
    if (!f.date) return setErr("La fecha es obligatoria.");
    const e1 = num(f.entry1);
    if (e1 === null) return setErr("Entry 1 es obligatoria.");
    const e2 = num(f.entry2);
    const trade = recompute({
      id: f.id || uid(),
      date: f.date,
      category: f.category,
      sub: f.category === "CFD" ? f.sub : "",
      broker: f.category === "SINTETICO" ? f.broker : "",
      asset: f.asset.trim(),
      direction: f.direction,
      entry1: e1,
      entry2: e2 === null ? "" : e2,
      activation: e2 === null ? "E1" : f.activation,
      sl: num(f.sl) ?? "",
      tps: parseTpsText(f.tpsText),
      pipSize: num(f.pipSize) || 1,
      legs: f.legs || {},
      discarded: !!f.discarded,
      chart: (f.chart || "").trim(),
      img: f.img || "",
      raw: f.raw || "",
      notes: (f.notes || "").trim(),
      tags: (f.tagsText || "").split(",").map((t) => t.trim()).filter(Boolean),
    });
    onSave(trade);
  };

  const showE2 = num(f.entry2) !== null;
  const auto = classifyAsset(f.asset);

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/70 p-4">
      <form onSubmit={submit} onPaste={onPasteImg} className="bx-card w-full max-w-3xl p-5 md:p-6 my-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-extrabold bx-accent tracking-wide">{f.id ? "EDITAR SEÑAL" : "NUEVA SEÑAL"}</h3>
          <button type="button" onClick={onCancel} className="bx-muted hover:text-white text-2xl leading-none">×</button>
        </div>

        {f.warnings?.length > 0 && (
          <div className="mb-3 rounded-xl text-xs p-3" style={{ background: "rgba(255,85,0,.12)", border: "1px solid rgba(255,85,0,.45)", color: "#ffb089" }}>
            ⚠ Revisa antes de guardar: {f.warnings.join(" · ")}
          </div>
        )}

        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <Field label="Fecha">
            <input type="date" className="bx-input" value={f.date} onChange={(e) => set("date", e.target.value)} />
          </Field>
          <Field label="Categoría">
            <select
              className="bx-input"
              value={f.category}
              onChange={(e) => {
                const cat = e.target.value;
                setF((p) => ({ ...p, category: cat, sub: cat === "CFD" ? p.sub || "Forex" : "", broker: cat === "SINTETICO" ? p.broker || "WELTRADE" : "" }));
              }}
            >
              <option value="CFD">CFDs</option>
              <option value="SINTETICO">Sintéticos</option>
            </select>
          </Field>
          {f.category === "CFD" ? (
            <Field label="Subcategoría CFD">
              <select className="bx-input" value={f.sub} onChange={(e) => set("sub", e.target.value)}>
                {CFD_SUBS.map((s) => <option key={s}>{s}</option>)}
              </select>
            </Field>
          ) : (
            <Field label="Broker">
              <select className="bx-input" value={f.broker} onChange={(e) => set("broker", e.target.value)}>
                {BROKERS.map((s) => <option key={s}>{s}</option>)}
              </select>
            </Field>
          )}
          <Field label="Dirección">
            <select className="bx-input" value={f.direction} onChange={(e) => set("direction", e.target.value)}>
              <option>BUY</option>
              <option>SELL</option>
            </select>
          </Field>

          <Field label="Activo" className="col-span-2">
            <input className="bx-input" placeholder="XAUUSD, NAS100, CRASH 900, GAINX 400..." value={f.asset} onChange={(e) => set("asset", e.target.value)} />
            {auto && (
              <div className="text-[11px] mt-1" style={{ color: "#ffb089" }}>
                Clasificación automática: {auto.category === "SINTETICO" ? `Sintético · ${auto.broker}` : `CFD · ${auto.sub}`}
              </div>
            )}
          </Field>
          <Field label={f.category === "CFD" ? "Valor de 1 pip (en precio)" : "Valor de 1 punto (en precio)"} className="col-span-2">
            <input
              type="number"
              step="any"
              className="bx-input"
              value={f.pipSize}
              onChange={(e) => { setPipTouched(true); set("pipSize", e.target.value); }}
              placeholder="Oro 0.1 · Forex 0.0001 · Índices/Sintéticos 1"
            />
          </Field>

          <Field label="Entry 1">
            <input type="number" step="any" className="bx-input" value={f.entry1} onChange={(e) => set("entry1", e.target.value)} />
          </Field>
          <Field label="Entry 2 (opcional)">
            <input type="number" step="any" className="bx-input" value={f.entry2} onChange={(e) => set("entry2", e.target.value)} />
          </Field>
          <Field label="Stop Loss">
            <input type="number" step="any" className="bx-input" value={f.sl} onChange={(e) => set("sl", e.target.value)} />
          </Field>
          <Field label="Entradas activadas">
            <select className="bx-input" value={showE2 ? f.activation : "E1"} disabled={!showE2} onChange={(e) => set("activation", e.target.value)}>
              <option value="E1">Solo E1</option>
              <option value="E2">Solo E2</option>
              <option value="BOTH">Ambas (E1 + E2)</option>
            </select>
          </Field>

          <Field label="Take Profits (separados por coma; usa OPEN para TP abierto)" className="col-span-2 md:col-span-4">
            <input className="bx-input" placeholder="4013, 4008, 4003, OPEN" value={f.tpsText} onChange={(e) => set("tpsText", e.target.value)} />
          </Field>

          <Field label="Enlace de gráfico (TradingView / imagen)" className="col-span-2 md:col-span-4">
            <input className="bx-input" placeholder="https://www.tradingview.com/x/..." value={f.chart} onChange={(e) => set("chart", e.target.value)} />
          </Field>

          <Field label="Captura (sube un archivo o pégala con Ctrl+V)" className="col-span-2 md:col-span-4">
            <div className="flex items-center gap-3 flex-wrap">
              <input type="file" accept="image/*" onChange={(e) => addImage(e.target.files?.[0])} className="bx-file" />
              {f.img && (
                <>
                  <img src={f.img} alt="" className="h-16 rounded-lg" style={{ border: "1px solid #2A2A2A" }} />
                  <button type="button" onClick={() => set("img", "")} className="text-xs text-rose-400">Quitar</button>
                </>
              )}
            </div>
          </Field>

          <Field label="Señal original (texto)" className="col-span-2 md:col-span-4">
            <textarea rows={3} className="bx-input text-xs" value={f.raw} onChange={(e) => set("raw", e.target.value)} />
          </Field>
          <Field label="Etiquetas (separadas por coma)" className="col-span-2 md:col-span-4">
            <input className="bx-input" placeholder="VIP Signal, Scalping" value={f.tagsText} onChange={(e) => set("tagsText", e.target.value)} />
          </Field>
          <Field label="Notas" className="col-span-2 md:col-span-4">
            <textarea rows={3} className="bx-input" value={f.notes} onChange={(e) => set("notes", e.target.value)} />
          </Field>

          <label className="col-span-2 md:col-span-4 flex items-center gap-2 text-sm cursor-pointer">
            <input type="checkbox" checked={!!f.discarded} onChange={(e) => set("discarded", e.target.checked)} />
            <span className="bx-muted">Señal descartada (no se ejecutó / se canceló)</span>
          </label>
        </div>

        {err && <div className="mt-3 text-sm text-rose-400">{err}</div>}

        <div className="mt-5 flex justify-end gap-2">
          <button type="button" onClick={onCancel} className="bx-ghost">Cancelar</button>
          <button type="submit" className="bx-btn">Guardar</button>
        </div>
      </form>
    </div>
  );
}

/* ----------------------------- TP chips ----------------------------- */
const TpChips = ({ t }) => {
  const l = t.tps || [];
  if (!l.length) return <span className="bx-muted text-xs">—</span>;
  const hm = hitMax(t);
  return (
    <div className="flex flex-wrap gap-1">
      {l.map((x, i) => {
        const hit = i <= hm;
        return (
          <span
            key={i}
            className="text-[11px] px-1.5 py-0.5 rounded-md whitespace-nowrap"
            style={
              hit
                ? { background: "rgba(16,185,129,.15)", border: "1px solid rgba(16,185,129,.5)", color: "#6ee7b7", fontWeight: 700 }
                : { border: "1px solid #2A2A2A", color: GREY }
            }
          >
            {hit ? "✓ " : ""}{x === "OPEN" ? tpLabel(i, x) : `${tpLabel(i, x)} ${x}`}
          </span>
        );
      })}
    </div>
  );
};

/* ----------------------------- Gestión por entrada (pata) ----------------------------- */
function LegEditor({ t, k, onChange }) {
  const L = legOf(t, k);
  const entry = entryOf(t, k);
  const unit = unitName(t);
  const tps = t.tps || [];
  const [pipsText, setPipsText] = useState("");

  useEffect(() => {
    setPipsText(L.pips === "" || L.pips === undefined || L.pips === null ? "" : String(L.pips));
  }, [L.pips, L.status, L.tpIdx]);

  const pickTp = (i) => {
    const lvl = tps[i];
    if (lvl === "OPEN") onChange(k, { status: "TP", tpIdx: i, exit: "OPEN", pips: L.exit === "OPEN" ? L.pips : "" });
    else {
      const p = calcPips(t, k, lvl);
      onChange(k, { status: "TP", tpIdx: i, exit: lvl, pips: p === null ? "" : p });
    }
  };
  const pickSL = () => {
    const p = calcPips(t, k, t.sl);
    onChange(k, { status: "SL", tpIdx: null, exit: t.sl, pips: p === null ? "" : p });
  };
  const pickBE = () => onChange(k, { status: "BE", tpIdx: null, exit: entry ?? "", pips: 0 });
  const pickOpen = () => onChange(k, { status: "Abierta", tpIdx: null, exit: "", pips: "" });

  const commitPips = () => {
    let v = num(pipsText);
    if (v !== null && L.status === "SL" && v > 0) v = -v;
    onChange(k, { pips: v === null ? "" : v });
  };

  const risk = riskPips(t, k);
  const p = num(L.pips);
  const r = p !== null && risk ? p / risk : null;
  const isOpenTp = L.status === "TP" && L.exit === "OPEN";
  const needsPips = L.status !== "Abierta" && p === null;

  return (
    <div className="rounded-xl p-3" style={{ background: "#161616", border: "1px solid #2A2A2A" }}>
      <div className="flex items-center justify-between mb-2 flex-wrap gap-1">
        <div className="text-sm font-bold">
          Entry {k === "e1" ? 1 : 2} <span className="bx-muted font-normal">@ {entry ?? "—"}</span>
        </div>
        <div className="text-xs bx-muted">{risk ? `Riesgo: ${Math.round(risk * 10) / 10} ${unit.toLowerCase()}` : "Sin SL"}</div>
      </div>

      <div className="flex flex-wrap gap-1.5">
        <button type="button" onClick={pickOpen} className={`bx-seg open ${L.status === "Abierta" ? "on" : ""}`}>Abierta</button>
        <button type="button" onClick={pickSL} className={`bx-seg neg ${L.status === "SL" ? "on" : ""}`}>Tocó SL</button>
        <button type="button" onClick={pickBE} className={`bx-seg mid ${L.status === "BE" ? "on" : ""}`}>BE / BE+</button>
        {tps.map((lvl, i) => (
          <button key={i} type="button" onClick={() => pickTp(i)} className={`bx-seg pos ${L.status === "TP" && L.tpIdx === i ? "on" : ""}`}>
            {tpLabel(i, lvl)}{lvl !== "OPEN" ? ` · ${lvl}` : ""}
          </button>
        ))}
      </div>

      {L.status !== "Abierta" && (
        <div className="mt-3 flex items-end gap-3 flex-wrap">
          <label className="block w-48">
            <span className="bx-label">{unit} reales</span>
            <input
              type="number"
              step="any"
              className="bx-input"
              value={pipsText}
              onChange={(e) => setPipsText(e.target.value)}
              onBlur={commitPips}
              onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); commitPips(); } }}
              placeholder={isOpenTp ? "Obligatorio" : "Editable"}
            />
          </label>
          <div className="text-xs bx-muted pb-2">{r !== null ? `${r >= 0 ? "+" : ""}${r.toFixed(2)}R` : ""}</div>
          {(isOpenTp || needsPips) && (
            <div className="text-xs pb-2" style={{ color: "#ffb089" }}>
              {isOpenTp ? "TP abierto: escribe los pips/puntos reales alcanzados." : "Escribe los pips/puntos reales."}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ----------------------------- Panel de gestión (admin) ----------------------------- */
function ManagePanel({ t, onUpdate }) {
  const keys = legKeys(t);
  const unit = unitName(t);
  const upd = (patch) => onUpdate(recompute({ ...t, ...patch }));
  const setLeg = (k, patch) => upd({ legs: { ...(t.legs || {}), [k]: { ...legOf(t, k), ...patch } } });

  const onFile = async (file) => {
    if (!file || !file.type.startsWith("image/")) return;
    try { upd({ img: await compressImage(file) }); } catch (e) {}
  };

  return (
    <div className="mt-5 rounded-xl p-4 space-y-4" style={{ background: "#0F0F0F", border: "1px solid #2A2A2A" }}>
      <div className="text-[11px] uppercase tracking-[0.18em] font-bold bx-accent">Gestión rápida (Admin)</div>

      {t.discarded ? (
        <button type="button" onClick={() => upd({ discarded: false })} className="bx-btn">Reabrir señal</button>
      ) : (
        <>
          {hasE2(t) && (
            <div>
              <div className="text-[11px] bx-muted mb-1">¿Qué entradas se activaron?</div>
              <div className="flex flex-wrap gap-1.5">
                {[["E1", "Solo E1"], ["E2", "Solo E2"], ["BOTH", "Ambas (E1 + E2)"]].map(([v, label]) => (
                  <button key={v} type="button" onClick={() => upd({ activation: v })} className={`bx-seg acc ${t.activation === v ? "on" : ""}`}>{label}</button>
                ))}
              </div>
            </div>
          )}

          {keys.map((k) => <LegEditor key={k} t={t} k={k} onChange={setLeg} />)}

          <div className="flex items-center justify-between flex-wrap gap-2 rounded-xl px-3 py-2" style={{ background: "#161616", border: "1px solid #2A2A2A" }}>
            <div className="text-xs bx-muted uppercase tracking-wider">Total de la señal</div>
            <div className={`text-lg font-extrabold ${t.pips > 0 ? "text-emerald-400" : t.pips < 0 ? "text-rose-400" : "text-white"}`}>
              {fmtP(t.pips)} {unit.toLowerCase()} <span className="text-xs bx-muted font-normal">· {t.r >= 0 ? "+" : ""}{t.r}R</span>
            </div>
          </div>

          <button type="button" onClick={() => upd({ discarded: true })} className="bx-ghost text-xs">Descartar señal (no ejecutada)</button>
        </>
      )}

      <div className="flex items-center gap-3 flex-wrap">
        <input type="file" accept="image/*" onChange={(e) => onFile(e.target.files?.[0])} className="bx-file" />
        {t.img && <button type="button" onClick={() => upd({ img: "" })} className="text-xs text-rose-400">Quitar captura</button>}
      </div>
    </div>
  );
}

/* ----------------------------- Detalle ----------------------------- */
function DetailModal({ t, onClose, isAdmin, onUpdate }) {
  if (!t) return null;
  const where = t.category === "CFD" ? `CFD · ${t.sub}` : `Sintético · ${t.broker}`;
  const unit = unitWord(t);
  const keys = legKeys(t);
  const hasRes = legResults(t).length > 0;
  const rows = [
    ["Fecha", fmtDate(t.date)],
    ["Mercado", where],
    ["Entry 1", t.entry1 === "" ? "—" : t.entry1],
    ["Entry 2", hasE2(t) ? t.entry2 : "—"],
    ["Activación", hasE2(t) ? (t.activation === "BOTH" ? "Ambas" : t.activation === "E2" ? "Solo E2" : "Solo E1") : "E1"],
    ["Stop Loss", t.sl === "" ? "—" : t.sl],
    ["Resultado", t.discarded || !hasRes ? "—" : `${fmtP(t.pips)} ${unit}`],
    ["Ratio R", t.discarded || !hasRes ? "—" : `${t.r >= 0 ? "+" : ""}${t.r}R`],
    ["1 pip/punto", t.pipSize],
  ];
  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/75 p-4" onClick={onClose}>
      <div className="bx-card w-full max-w-2xl p-5 md:p-6 my-6" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-start justify-between">
          <div>
            <div className="flex items-center gap-2 flex-wrap">
              <h3 className="text-xl font-extrabold">{t.asset}</h3>
              <DirBadge dir={t.direction} />
              <StatusBadge status={t.status} />
            </div>
            <div className="text-xs bx-muted mt-1">{where}</div>
          </div>
          <button onClick={onClose} className="bx-muted hover:text-white text-2xl leading-none">×</button>
        </div>

        <div className="grid grid-cols-3 gap-2 mt-4">
          {rows.map(([k, v]) => (
            <div key={k} className="rounded-lg p-2" style={{ background: "#0F0F0F", border: "1px solid #2A2A2A" }}>
              <div className="text-[10px] uppercase tracking-wider bx-muted">{k}</div>
              <div className={`text-sm font-semibold ${k === "Resultado" ? (t.pips > 0 ? "text-emerald-400" : t.pips < 0 ? "text-rose-400" : "text-white") : "text-white"}`}>{v}</div>
            </div>
          ))}
        </div>

        {!t.discarded && hasE2(t) && keys.length > 1 && (
          <div className="mt-3 rounded-xl p-3 text-sm space-y-1" style={{ background: "#0F0F0F", border: "1px solid #2A2A2A" }}>
            {keys.map((k) => (
              <div key={k} className="flex justify-between gap-2">
                <span className="bx-muted">Entry {k === "e1" ? 1 : 2} @ {entryOf(t, k)}</span>
                <span className="font-semibold">{legSummary(t, k)}</span>
              </div>
            ))}
          </div>
        )}

        <div className="mt-4"><TpChips t={t} /></div>

        {t.tags?.length > 0 && (
          <div className="mt-3 flex flex-wrap gap-1.5">
            {t.tags.map((g) => (
              <span key={g} className="text-[11px] px-2 py-0.5 rounded-full" style={{ border: "1px solid rgba(255,85,0,.5)", color: "#ffb089" }}>#{g}</span>
            ))}
          </div>
        )}

        {t.notes && <p className="mt-4 text-sm whitespace-pre-wrap" style={{ color: "#D6D1C9" }}>{t.notes}</p>}

        {imgSrc(t) && (
          <img
            src={imgSrc(t)}
            alt="Captura de la operación"
            className="mt-4 w-full rounded-xl"
            style={{ border: "1px solid #2A2A2A" }}
            onError={(e) => { e.currentTarget.style.display = "none"; }}
          />
        )}

        {t.chart && (
          <a href={t.chart} target="_blank" rel="noopener noreferrer" className="mt-3 inline-block text-sm bx-accent underline">
            Abrir gráfico en TradingView ↗
          </a>
        )}

        {t.raw && (
          <details className="mt-4">
            <summary className="cursor-pointer text-xs uppercase tracking-wider bx-muted">Señal original</summary>
            <pre className="mt-2 whitespace-pre-wrap text-xs rounded-xl p-3" style={{ background: "#0F0F0F", color: GREY, border: "1px solid #2A2A2A" }}>{t.raw}</pre>
          </details>
        )}

        {isAdmin && <ManagePanel key={t.id} t={t} onUpdate={onUpdate} />}
      </div>
    </div>
  );
}

